// The dial position is 0, 1, or 2 starting at 1. Turn up decreases it, turn down increases it (clamped). Waiting does not change it. The room becomes warm when the dial is 1, cold when it is 2, and keeps its previous state when the dial is 0.
function visible(actions) {
  let dial = 1;
  let room = "cold";
  for (let a of actions) {
    if (a === "turn up") dial = Math.max(dial - 1, 0);
    else if (a === "turn down") dial = Math.min(dial + 1, 2);
    // wait: dial unchanged
    if (dial === 1) room = "warm";
    else if (dial === 2) room = "cold";
    // dial === 0: room keeps its previous state
  }
  return { room };
}

