// Track dial position (start 0): U +1, D -1, W 0. Room is warm unless dial ever reaches 2+ or ends with a down-turn while dial is negative.
function visible(actions) {
  let dial = 0;
  let maxDial = 0;
  let lastAction = null;

  for (const action of actions) {
    if (action === "turn up") {
      dial += 1;
    } else if (action === "turn down") {
      dial -= 1;
    }
    // "wait" leaves dial unchanged
    if (dial > maxDial) maxDial = dial;
    lastAction = action;
  }

  const isCold =
    maxDial >= 2 ||
    (lastAction === "turn down" && dial < 0);

  return { room: isCold ? "cold" : "warm" };
}

