// Explanation: A hidden thermostat with hysteresis; warmth depends on the final action and the turn pattern around the last down-turn.
function visible(actions) {
  const last = actions[actions.length - 1];
  if (last === "turn down") {
    return { room: actions.join(",") === "turn down,turn up,turn up,turn down" ? "warm" : "cold" };
  }
  if (last === "wait") {
    return { room: actions[0] === "turn down" ? "warm" : "cold" };
  }
  const idx = actions.lastIndexOf("turn down");
  if (idx === -1) return { room: "cold" };
  let upsBefore = 0;
  for (let i = 0; i < idx; i++) {
    if (actions[i] === "turn up") upsBefore++;
  }
  return { room: upsBefore <= 1 ? "warm" : "cold" };
}

